create table wksp_dtesc.sgt_evento_comentario (
    id              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    evento_id       number not null enable,
    tipo_comentario varchar2(50 byte) default 'TECNICO' not null enable,
    texto           varchar2(2000 byte) not null enable,
    autor           varchar2(255 byte) not null enable,
    fecha_creacion  timestamp(6) default systimestamp not null enable,
    creado_por      varchar2(255 byte),
    creado_el       timestamp(6) default systimestamp
);

alter table wksp_dtesc.sgt_evento_comentario
    add constraint pk_sgt_evento_comentario primary key ( id )
        using index enable;


